Add-Type -AssemblyName System.Drawing; $img = [System.Drawing.Image]::FromFile('public\images\quiz1.png'); $bmp = new-object System.Drawing.Bitmap($img); $r=0;$g=0;$b=0; for($y=0; $y -lt $bmp.Height; $y++) { $pixel = $bmp.GetPixel(0, $y); $r+=$pixel.R; $g+=$pixel.G; $b+=$pixel.B; }; $r=[int][math]::Round($r/$bmp.Height); $g=[int][math]::Round($g/$bmp.Height); $b=[int][math]::Round($b/$bmp.Height); Write-Output ('#' + $r.ToString('X2') + $g.ToString('X2') + $b.ToString('X2'))
